<?php

declare(strict_types=1);

use Careminate\Foundation\Application;
use Careminate\Http\Kernel;
use Careminate\Http\Middleware\ExceptionHandler;
use Careminate\Http\Middleware\Middleware;
use Careminate\Http\Request;
use Careminate\Http\Response;

return static function (): Kernel {
    $application = new Application();
    $kernel = new Kernel($application);

    // Converts application exceptions into safe HTTP responses.
    $kernel->middleware(new ExceptionHandler());

    // Add a security header to all normal HTTP responses,
    // including errors generated by the router.
    $kernel->middleware(
        new class implements Middleware {
            public function process(
                Request $request,
                Closure $next,
            ): Response {
                return $next($request)->withHeader(
                    'X-Frame-Options',
                    'DENY',
                );
            }
        },
    );

    // HTML frontend controller.
    $kernel->router()->get(
        '/',
        static function (Request $request): Response {
            $html = <<<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport"
          content="width=device-width, initial-scale=1">
    <title>Careminate Framework</title>
    <style>
        :root {
            color-scheme: dark;
            font-family: system-ui, sans-serif;
        }
        body {
            margin: 0;
            min-height: 100vh;
            display: grid;
            place-items: center;
            background: #0f172a;
            color: #e2e8f0;
        }
        main {
            width: min(90%, 680px);
            padding: 32px;
            border: 1px solid #334155;
            border-radius: 16px;
            background: #1e293b;
        }
        h1 { color: #38bdf8; }
        a { color: #7dd3fc; }
        .status {
            padding: 12px;
            border-radius: 8px;
            background: #0f172a;
        }
        pre { white-space: pre-wrap; }
    </style>
</head>
<body>
<main>
    <h1>Careminate Framework</h1>
    <p>Frontend Controller Integration Demo</p>
    <p>
        This page is served through the Careminate
        HTTP runtime, middleware pipeline and router.
    </p>

    <h2>Application Status</h2>
    <pre id="status" class="status">Loading...</pre>

    <nav>
        <a href="/health">Health Check</a>
        |
        <a href="/api/status">JSON API</a>
    </nav>
</main>

<script>
    fetch('/api/status')
        .then(response => {
            if (!response.ok) {
                throw new Error('HTTP ' + response.status);
            }
            return response.json();
        })
        .then(data => {
            document.getElementById('status')
                .textContent = JSON.stringify(data, null, 2);
        })
        .catch(() => {
            document.getElementById('status')
                .textContent = 'API unavailable';
        });
</script>
</body>
</html>
HTML;

            return new Response(
                200,
                [
                    'Content-Type' => 'text/html; charset=utf-8',
                    'Content-Security-Policy' =>
                    "default-src 'self'; "
                        . "style-src 'unsafe-inline'; "
                        . "script-src 'unsafe-inline'; "
                        . "connect-src 'self'; "
                        . "object-src 'none'; "
                        . "base-uri 'none'; "
                        . "frame-ancestors 'none'",
                    'X-Content-Type-Options' => 'nosniff',
                ],
                $html,
            );
        },
    );

    // Health check.
    $kernel->router()->get(
        '/health',
        static fn(Request $request): Response =>
        new Response(
            200,
            ['Content-Type' => 'text/plain; charset=utf-8'],
            'Careminate OK',
        ),
    );

    // JSON API.
    $kernel->router()->get(
        '/api/status',
        static fn(Request $request): Response =>
        new Response(
            200,
            [
                'Content-Type' => 'application/json',
                'Cache-Control' => 'no-store',
            ],
            json_encode(
                [
                    'framework' => 'Careminate',
                    'status' => 'running',
                    'php' => PHP_VERSION,
                ],
                JSON_THROW_ON_ERROR,
            ),
        ),
    );

    // JSON echo endpoint.
    $kernel->router()->post(
        '/api/echo',
        static function (Request $request): Response {
            try {
                $data = json_decode(
                    $request->body,
                    true,
                    512,
                    JSON_THROW_ON_ERROR,
                );
            } catch (\JsonException) {
                return new Response(
                    400,
                    ['Content-Type' => 'application/json'],
                    '{"error":"invalid JSON"}',
                );
            }

            if (
                !is_array($data)
                || !isset($data['message'])
                || !is_string($data['message'])
            ) {
                return new Response(
                    400,
                    ['Content-Type' => 'application/json'],
                    '{"error":"message must be a string"}',
                );
            }

            return new Response(
                200,
                ['Content-Type' => 'application/json'],
                json_encode(
                    ['message' => $data['message']],
                    JSON_THROW_ON_ERROR,
                ),
            );
        },
    );

    return $kernel;
};
